  .byte DMC_SEQ_A, DMC_SEQ_A, DMC_SEQ_C, DMC_SEQ_D, DMC_SEQ_A ;-D-- 03DB6 BDA6: 10 10 40 80 10
HitPoseMap:                       ; playerPose -> pose after being hit
  .byte $00, $01, $02, $03, $04, $04, $04, $03 ;---- 03DBB BDAB: 00 01 02 03 04 04 04 03
  .byte $02, $00, $00             ;-D-- 03DC3 BDB3: 02 00 00
KnifeThrowerMinX:                 ; by floorGoesRight: a thrower facing right stops walking in at page FLOOR_X_MAX_HI, X >= this
  .byte $F0, $B0                  ;-D-- 03DC6 BDB6: F0 B0
KnifeThrowerMaxX:                 ; by floorGoesRight: a thrower facing left stops at page 0, X < this
  .byte $4A, $10                  ;-D-- 03DC8 BDB8: 4A 10
SetKnifeThrowParams:              ; throwerTurnDelay, throwsPerTurn, lowThrowChance by difficulty and floor
  LDX difficulty                  ;C-J- 03DCA BDBA: A6 BE
  LDA KnifeTurnDelay,X            ;C--- 03DCC BDBC: BD 76 BB
  STA throwerTurnDelay            ;C--- 03DCF BDBF: 8D 82 03
  LDA KnifeThrowsPerTurn,X        ;C--- 03DD2 BDC2: BD 82 BB
  STA throwsPerTurn               ;C--- 03DD5 BDC5: 8D 81 03
  LDY floor                       ;C--- 03DD8 BDC8: A4 5F
  CPX #$02                        ;C--- 03DDA BDCA: E0 02
  BCS @skip                       ;C--- 03DDC BDCC: B0 05
  LDA KnifeLowChance,Y            ;C--- 03DDE BDCE: B9 71 BB
  BNE @skip3                      ;C--- 03DE1 BDD1: D0 0A
@skip:
  CPX #$02                        ;T--- 03DE3 BDD3: E0 02
  BNE @skip2                      ;T--- 03DE5 BDD5: D0 04
  LDA #KNIFE_LOW_CHANCE_D2        ;T--- 03DE7 BDD7: A9 66
  BNE @skip3                      ;T--- 03DE9 BDD9: D0 02
@skip2:
  LDA #KNIFE_LOW_CHANCE_D3        ;T--- 03DEB BDDB: A9 80
@skip3:
  STA lowThrowChance              ;C-J- 03DED BDDD: 8D 83 03
  RTS                             ;C--- 03DF0 BDE0: 60
